#pragma once
#include "texture_decode.h"
#include <QVector>
#include <QJsonObject>
namespace FafSurface {
struct Texture {QString name,error; qint64 at=0,size=0;int bw=0,bh=0,width=0,height=0,mips=0,palettes=0,format=-1;bool external=false;};
struct Binding {QString name,error;int image=-1,passes=0,wrapU=1,wrapV=1;};
inline Texture texture(const QByteArray &bytes,qint64 at,qint64 size,QString name,bool external){Texture t;t.name=name;t.at=at;t.size=size;t.external=external;if(external){t.error="External image reference; no pixels in this bank.";return t;}if(at<0||size<20||at>bytes.size()-size){t.error="Incomplete ARCX texture header.";return t;}auto h=[&](int p){return qFromLittleEndian<quint16>(bytes.constData()+at+p);};t.bw=h(0);t.bh=h(2);t.width=h(4);t.height=h(6);t.mips=h(8);t.palettes=h(10);t.format=qFromLittleEndian<quint32>(bytes.constData()+at+12);if(!imageValidSize(t.bw,t.bh)||t.width<1||t.height<1||t.width>t.bw||t.height>t.bh||t.mips<1||t.mips>16||t.palettes>16)t.error="Invalid ARCX texture dimensions/mip/palette count.";return t;}
inline QString format(int f){switch(f){case 12:return "BC1";case 14:return "BC2";case 15:return "BC3";case 11:return "Indexed8";case 6:case 18:return "BGRA8";case 2:case 16:return "ARGB1555";case 4:return "RGBA4444";case 25:return "Gray8";default:return {};}}
inline QImage decode(const QByteArray &bytes,const Texture &t,int mip,int paletteBank,QString &error,const std::atomic_bool &cancel){auto fail=[&](QString e){error=e;return QImage();};if(!t.error.isEmpty())return fail(t.error);if(mip<0||mip>=t.mips||paletteBank<0)return fail("ARCX image mip/palette index is out of range.");ImageRecipe recipe;recipe.width=t.bw;recipe.height=t.bh;recipe.format=format(t.format);if(recipe.format.isEmpty())return fail(QString("Unsupported Xbox texture format 0x%1.").arg(t.format,0,16));bool block=imageBlockCompressed(recipe.format);recipe.layout=block||t.format==18||t.format==16?"Linear":"Morton rectangular";qint64 start=t.at+20,end=t.at+t.size;QByteArray palette;
    if(t.format==11){if(t.mips!=1||t.palettes<1||paletteBank>=t.palettes)return fail("Unsupported ARCX P8 mip layout or palette index.");qint64 pixels=qint64(t.bw)*t.bh,padded=(pixels+511)&~qint64(511),paletteStart=end-qint64(t.palettes)*1024;if(paletteStart!=start+padded)return fail("ARCX P8 palette/index spans disagree.");palette=bytes.mid(paletteStart+paletteBank*1024,1024);end=paletteStart;recipe.paletteFormat="BGRA8";recipe.paletteEntries=256;
    }else if(paletteBank)return fail("This ARCX image has no palette banks.");
    for(int i=0;i<mip;++i){QString e;auto span=imageSpan(recipe,e);if(!e.isEmpty()||span>end-start)return fail("Incomplete ARCX mip chain.");start+=span;recipe.width=qMax(1,recipe.width/2);recipe.height=qMax(1,recipe.height/2);}QString e;auto span=imageSpan(recipe,e);if(!e.isEmpty())return fail(e);if(span>end-start)return fail("ARCX texture data is truncated.");auto image=decodeTextureData(bytes.mid(start,span),palette,recipe,error,cancel);if(image.isNull())return image;
    if(t.format==4||t.format==25)for(int y=0;y<image.height();++y){if(cancel.load())return fail("ARCX image decoding canceled.");auto *row=reinterpret_cast<QRgb *>(image.scanLine(y));for(int x=0;x<image.width();++x){auto p=row[x];row[x]=t.format==25?qRgba(255,255,255,qRed(p)):qRgba(qGreen(p),qBlue(p),qAlpha(p),qRed(p));}}
    int width=qMax(1,t.width>>mip),height=qMax(1,t.height>>mip);return width==image.width()&&height==image.height()?image:image.copy(0,0,width,height);
}
inline Binding material(const QByteArray &bytes,qint64 at,qint64 size,QString name,int imageCount){Binding m;m.name=name;if(at<0||size<77||at>bytes.size()-size){m.error="Untextured or unsupported short material state.";return m;}auto u=[&](int p){return qFromLittleEndian<quint32>(bytes.constData()+at+p);};m.passes=u(29);qint64 image=qint64(u(0))+qFromLittleEndian<qint32>(bytes.constData()+at+57);if(m.passes<1||m.passes>32||image<0||image>=imageCount){m.error="Unsupported ARCX material color-image reference.";return m;}m.image=image;m.wrapU=u(61);m.wrapV=u(65);if(m.wrapU<1||m.wrapU>3||m.wrapV<1||m.wrapV>3)m.error="Unsupported ARCX texture addressing mode.";return m;}
inline QString wrap(int value){return value==3?"Clamp":value==2?"Mirror":"Repeat";}
}
